create temporary view view_source_table_${grass_region_without_quote} as
select
    pre_source.event_id as pre_event_id
    ,coalesce(lead(log_timestamp, 1) OVER(PARTITION BY deviceid, userid, session_id ORDER BY log_timestamp asc), cast(log_timestamp as BIGINT)) - cast(log_timestamp as BIGINT) as stay_duration
from
    traffic.shopee_traffic_dwd_event_stream_hi__reg_s1_live
where
    grass_region in (${grass_region})
    and (
        (regional_date = ${local_date} and regional_hour = ${local_hour})
        or (
            regional_date = date(date(${local_date}) + interval ${local_hour} hours + interval '1' hours)
            and regional_hour = hour(date(${local_date}) + interval ${local_hour} hours + interval '1' hours)
        )
        -- with the help of timezone_convert function
        --( regional_date = timezone_convert(${local_date}, ${local_hour}, "ID", "SG","yyyy-MM-dd") and regional_hour = timezone_convert(${local_date}, ${local_hour}, "ID", "SG", "H"))
    )
    and page_type = 'product'
    and operation = 'view'
;

--sql_divide_splitter--
create temporary view view_table_${grass_region_without_quote} as
select
    pre_event_id
    ,max(stay_duration) as stay_duration
from
    view_source_table_${grass_region_without_quote}
group by
    pre_event_id
;

