    and (
        (regional_date = ${local_date} and regional_hour = ${local_hour})
        or (regional_date = date(date(${local_date}) + interval ${local_hour} hours + interval '1' hours) and regional_hour = hour(date(${local_date}) + interval ${local_hour} hours + interval '1' hours))
    )
    and target_type = 'see_more_button'
    and page_type = 'product'
    and page_section[0] = 'product_detail'
;

--sql_divide_splitter--
create temporary view see_more_button_${grass_region_without_quote} as
