--sql_divide_splitter--
-- use utc(00 and 01) -> utc+8(08),so his marker is 01(should be 00 and 01)
create temporary view click_table_${grass_region_without_quote} as
select
    userid as user_id
    ,deviceid as device_id
    ,platform
    ,page_type
    ,pub_id
    ,pub_context_id
    ,coalesce(
        cast(get_json_object(data, '$.itemid') as BIGINT),
        cast(get_json_object(data, '$.item.itemid') as BIGINT),
        cast(get_json_object(data, '$.context.itemid') as BIGINT),
        cast(get_json_object(data, '$.search_params.itemid') as BIGINT)
    ) as item_id
    ,coalesce(
        cast(get_json_object(data, '$.shopid') as BIGINT),
        cast(get_json_object(data, '$.item.shopid') as BIGINT),
        cast(get_json_object(data, '$.context.shopid') as BIGINT),
        cast(get_json_object(data, '$.search_params.shopid') as BIGINT)
    ) as shop_id
    ,session_id
    ,event_id
    ,page_type
    ,event_timestamp
    ,log_timestamp
    ,regexp_extract(get_json_object(data, '$.recommendation_info'),'REQID:([^,]*)',1) as request_id
from
    traffic.shopee_traffic_dwd_event_stream_hi__reg_s1_live
where
    grass_region in (${grass_region})
    and regional_date = ${local_date}
    and regional_hour = ${local_hour}
    and operation = 'click'
    and target_type = 'item'
;

