create temporary view joined_table_${grass_region_without_quote} as
select
    t1.user_id
    ,t1.item_id
    ,t1.shop_id
    ,t1.device_id
    ,t1.platform
    ,t1.session_id
    ,t1.event_id
    ,t1.pub_id
    ,t1.pub_context_id
    ,t1.event_timestamp
    ,t1.log_timestamp
    ,t2.stay_duration
    ,coalesce(t3.see_more,false) as is_see_more
    ,t1.request_id
from
    click_table_${grass_region_without_quote} as t1
left join
    view_table_${grass_region_without_quote} as t2
on
    t1.event_id = t2.pre_event_id
left join
    see_more_button_${grass_region_without_quote} as t3
on
    t1.event_id = t3.pre_event_id
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_pdp_view_event_level_stay_duration_1h
partition (
    grass_region = ${grass_region}
    ,regional_date = ${local_date}
    ,regional_hour = ${local_hour}
)

select
    user_id
    ,item_id
    ,shop_id
    ,device_id
    ,platform
    ,session_id
    ,event_id
    ,pub_id
    ,pub_context_id
    ,event_timestamp
    ,log_timestamp
    ,stay_duration
    ,is_see_more
    ,request_id
from
    joined_table_${grass_region_without_quote}
where
    stay_duration > 0
    or is_see_more = true
